d:rgba(255,255,255,.96);box-shadow:0 12px 30px rgba(2,7,36,.25)}.composer{background:rgba(9,14,43,.94);border-color:rgba(137,157,255,.18)}.suggestions button{background:rgba(111,96,255,.2);color:#b9c7ff;border:1px solid rgba(135,153,255,.2)}.chat-send{background:rgba(255,255,255,.08);border-color:rgba(137,157,255,.35)}.chat-send:focus-within{background:rgba(255,255,255,.13);border-color:#67dcff}.chat-send textarea{color:#fff}.chat-send textarea::placeholder{color:#8e9bc4}.composer-hint{color:#8491bb}.tutor-main:after{content:"";position:absolute;inset:0;pointer-events:none;opacity:.12;background-image:linear-gradient(rgba(113,152,255,.25) 1px,transparent 1px),linear-gradient(90deg,rgba(113,152,255,.25) 1px,transparent 1px);background-size:34px 34px;mask-image:linear-gradient(140deg,#000,transparent 65%)}
