<script>
(()=>{const shell=document.querySelector('.tutor-shell');if(!shell||matchMedia('(prefers-reduced-motion: reduce)').matches||matchMedia('(max-width: 800px)').matches)return;let frame=0;shell.addEventListener('pointermove',e=>{const r=shell.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{shell.style.transform=`rotateX(${(-y*1.8).toFixed(2)}deg) rotateY(${(x*2.2).toFixed(2)}deg)`})});shell.addEventListener('pointerleave',()=>{shell.style.transform=''})})();
</script>
